import type { GeographyPack } from './engine';
import { microstates } from './microstates';
import map from './data/europe-map.json';

/** Bundled Natural Earth 1:50m outlines; generated by scripts/build-europe-map.py.
 * One coordinate system serves hidden/revealed labels, hit targets and zoom.
 */
export const europeShapes = map.countries;
export const europeContextShapes = map.context;
export const europePack: GeographyPack = {
  id: 'europe-countries', title: 'Europe', kind: 'country',
  locations: [...europeShapes.map(({ id, name, latitude, longitude }) =>
    ({ id, name, latitude, longitude, geometryId: id })), ...microstates],
};
